#include <stdio.h>

typedef struct { int num; char name[32]; double score; } Student;

int main(void) {
    Student a, b;
    scanf("%d%31s%lf", &a.num, a.name, &a.score);
    scanf("%d%31s%lf", &b.num, b.name, &b.score);
    Student best = a.score >= b.score ? a : b;
    printf("%d %s %.2f\n", best.num, best.name, best.score);
    return 0;
}
